sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    /**
     * Handles alert action events (open/dismiss).
     * 
     * Hides the renew alert and optionally navigates to the renewal task
     * record if the action type is 'open'.
     * 
     * @param {Object} event - Event object containing action details
     * @param {string} event.payload.action.type - Action type ('open' or other)
     * @param {string} event.payload.action.href - Task sys_id for navigation
     */

    const RENEW_TASK_TABLE = 'sn_disco_certmgmt_renew_task';

    const alertType = event.payload.action.type;

    // Always hide the alert regardless of action type
    api.setState('renew_alert', {
        ...api.state.renew_alert,
        show: false
    });

    // Navigate to renewal task record only for 'open' action
    if (alertType === 'open') {
        helpers.navigate.to('record', {
            table: RENEW_TASK_TABLE,
            sysId: event.payload.action.href
        });
    }
}
